1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.beans.factory.annotation.Autowired;
7	import org.springframework.data.domain.Page;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.repository.OwnerRepository;
10	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
11	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
12	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
13	
14	import java.time.LocalDate;
15	import java.util.Collection;
16	import java.util.List;
17	
18	/**
19	 * Maps Owner & OwnerDto using Mapstruct
20	 */
21	@Mapper(uses = PetMapper.class)
22	public abstract class OwnerMapper {
23	
24	    /**
25	     * More than this many owners already sharing a {@code registrationDate} raises the
26	     * {@code bulkSignupWarning} on responses for that day.
27	     */
28	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
29	
30	    /**
31	     * The hard per-city capacity limit: a city already holding this many owners rejects further
32	     * creates (see
33	     * {@link org.springframework.samples.petclinic.rest.function.owner.EnsureCityCapacity}).
34	     */
35	    private static final int CITY_CAPACITY_LIMIT = 50;
36	
37	    /**
38	     * A city already holding at least this many (but fewer than {@link #CITY_CAPACITY_LIMIT})
39	     * owners raises the {@code capacityWarning} on responses, signalling it is approaching the limit.
40	     */
41	    private static final int CITY_CAPACITY_WARNING_THRESHOLD = 40;
42	
43	    @Autowired
44	    protected OwnerRepository ownerRepository;
45	
46	    @Mapping(target = "displayName",
47	            expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
48	    @Mapping(target = "salutation", expression = "java(salutation(owner))")
49	    @Mapping(target = "initials",
50	            expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" + Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
51	    @Mapping(target = "fiscalYear", expression = "java(fiscalYear(owner))")
52	    @Mapping(target = "membershipPoints", expression = "java(membershipPoints(owner))")
53	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
54	    @Mapping(target = "locality", expression = "java(locality(owner))")
55	    @Mapping(target = "timezone", expression = "java(timezone(owner))")
56	    @Mapping(target = "bulkSignupWarning", expression = "java(bulkSignupWarning(owner))")
57	    @Mapping(target = "capacityWarning", expression = "java(capacityWarning(owner))")
58	    @Mapping(target = "riskFlag", expression = "java(riskFlag(owner))")
59	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
60	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
61	    @Mapping(target = "ownerSegment", expression = "java(ownerSegment(owner))")
62	    @Mapping(target = "identityKey",
63	            expression = "java(org.springframework.samples.petclinic.rest.function.owner.OwnerIdentity.key(owner))")
64	    @Mapping(target = "telephoneDisplay",
65	            expression = "java(org.springframework.samples.petclinic.rest.function.owner.Telephones.toDisplay(owner.getTelephone()))")
66	    @Mapping(target = "selfLink", expression = "java(selfLink(owner))")
67	    public abstract OwnerDto toOwnerDto(Owner owner);
68	
69	    /**
70	     * The canonical API path to this owner: {@code /api/owners/} followed by the owner's id.
71	     * Returns {@code null} when the owner has no id (e.g. before it has been persisted).
72	     */
73	    protected String selfLink(Owner owner) {
74	        return owner.getId() == null ? null : "/api/owners/" + owner.getId();
75	    }
76	
77	    /**
78	     * The owner's {@code membershipPoints}: the raw loyalty score (see
79	     * {@link org.springframework.samples.petclinic.rest.function.owner.Memberships}), built from a
80	     * present email, no namesakes, a household of 3 or more and tenure over one elapsed fiscal year.
81	     */
82	    protected int membershipPoints(Owner owner) {
83	        long householdSize = org.springframework.samples.petclinic.rest.function.owner.Households
84	                .size(owner, ownerRepository);
85	        return org.springframework.samples.petclinic.rest.function.owner.Memberships
86	                .membershipPoints(owner, householdSize);
87	    }
88	
89	    /**
90	     * The owner's {@code membershipLevel}: the grade {@code membershipPoints} buckets into — 1 for
91	     * 0-1 points, 2 for 2-3, 3 for 4-5 and 4 for 6 or more — after the household level ceiling, which
92	     * caps a member at one above the current maximum level among the household members that already
93	     * existed when it joined (see
94	     * {@link org.springframework.samples.petclinic.rest.function.owner.Memberships#cappedLevel}).
95	     */
96	    protected int membershipLevel(Owner owner) {
97	        return org.springframework.samples.petclinic.rest.function.owner.Memberships
98	                .cappedLevel(owner, ownerRepository);
99	    }
100	
101	    /**
102	     * The owner's preferred contact channel: {@code EMAIL} when an email address is
103	     * present (non-null and non-blank), otherwise {@code PHONE}.
104	     */
105	    protected OwnerDto.ContactPreferenceEnum contactPreference(Owner owner) {
106	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
107	        return hasEmail ? OwnerDto.ContactPreferenceEnum.EMAIL : OwnerDto.ContactPreferenceEnum.PHONE;
108	    }
109	
110	    /** The age (in years) at which an owner stops being a minor and becomes an adult. */
111	    private static final int ADULT_AGE = 18;
